package com.subrosa.desktop

import java.io.File

/**
 * KL-13, desktop half of the on-device format check. No server, no GUI, no
 * network: it drives the real desktop `InviteCodeManager` so that a code
 * generated by a physical Android phone can be handed to this parser, and a
 * code generated here can be handed to the phone.
 *
 * Why this exists next to InviteLiveRun.kt: that harness needs a running
 * server and a live first contact, which needs the phone's GUI. The question
 * KL-13 actually records -- "the Android and Desktop invite-code format was
 * incompatible" -- is settled without either, and settling it needs the code
 * to come off a real device, because the Android side encodes with
 * `android.util.Base64` and signs with the device's own ECDSA provider.
 * The Android unit test for the shared vectors runs under Robolectric, whose
 * `android.util.Base64` is a reimplementation on the host JVM, so it cannot
 * answer that part.
 *
 * Usage:
 *   gen   <outFile>    write a freshly generated invite code for the phone
 *   check <codeFile>   parse + verify a code the phone generated
 *
 * Set APPDATA to a throwaway directory: DesktopStorage.init() would otherwise
 * use the real desktop profile on this machine and mint an invite against the
 * owner's own identity.
 */
fun main(args: Array<String>) {
    val mode = args.getOrNull(0)
        ?: error("usage: gen <outFile> | check <codeFile>")

    DesktopStorage.init()
    DesktopCryptoManager.init()
    CryptoManager.init()

    when (mode) {
        "gen" -> {
            val out = File(args.getOrNull(1) ?: error("gen needs <outFile>"))
            val code = InviteCodeManager.generateInviteLink()
            out.writeText(code)
            val data = InviteCodeManager.parseInviteCode(code)
                ?: error("desktop cannot parse the code it just generated")
            println("[desktop] generated: len=${code.length} fp=${data.fingerprint} " +
                    "name=${data.displayName} tag=${data.mailboxTag} " +
                    "self-verify=${InviteCodeManager.verifyInviteCode(data)}")
            println("[desktop] prefix=${code.take(12)}…")
            println("[desktop] written to ${out.absolutePath}")
        }

        "check" -> {
            val file = File(args.getOrNull(1) ?: error("check needs <codeFile>"))
            val code = file.readText().trim()
            println("[desktop] read ${code.length} chars from ${file.absolutePath}, prefix=${code.take(12)}…")
            val data = InviteCodeManager.parseInviteCode(code)
            if (data == null) {
                println("[desktop] FAIL: parseInviteCode rejected the phone-generated code")
                kotlin.system.exitProcess(3)
            }
            val verified = InviteCodeManager.verifyInviteCode(data)
            println("[desktop] parsed: fp=${data.fingerprint} name=${data.displayName} " +
                    "tag=${data.mailboxTag} ts=${data.timestamp} verify=$verified")
            if (!verified) {
                println("[desktop] FAIL: verifyInviteCode refused the phone-generated code")
                kotlin.system.exitProcess(4)
            }
            println("[desktop] OK: phone-generated code parses and verifies here")
        }

        else -> error("unknown mode: $mode")
    }
    kotlin.system.exitProcess(0)
}
